import React, { useEffect, useState } from "react";
import axios from "axios";
import ParentFeePage from "./ParentFeePage";
import "../styles/main.css";
import { getApplicableFeeKeys } from "../utils/feeRules";

export default function AdminStudentsFees() {
  const [students, setStudents] = useState([]);
  const [selectedStudent, setSelectedStudent] = useState(null);
  const [fee, setFee] = useState({});
  const [overrides, setOverrides] = useState({});
  const [showPayPopup, setShowPayPopup] = useState(false);

  useEffect(() => {
    const fetchStudents = async () => {
      try {
        const token = localStorage.getItem("token");
        const res = await axios.get("http://localhost:5000/api/admin/students", {
          headers: { Authorization: `Bearer ${token}` },
        });
        setStudents(res.data || []);
      } catch (err) {
        console.error(err);
      }
    };
    fetchStudents();
  }, []);

  useEffect(() => {
    const fetchFee = async () => {
      try {
        const token = localStorage.getItem("token");
        const res = await axios.get("http://localhost:5000/api/admin/fee-structure", {
          headers: { Authorization: `Bearer ${token}` },
        });
        setFee(res.data || {});
      } catch (err) {
        console.error(err);
      }
    };
    fetchFee();
  }, []);

  const handleStudentSelect = (stu) => {
    setSelectedStudent(stu);
    const applicableKeys = getApplicableFeeKeys(stu.className);
    const filtered = {};
    Object.keys(fee.items || {}).forEach((key) => {
      if (applicableKeys.includes(key))
        filtered[key] = fee.items[key].amount;
    });
    setOverrides(filtered);
  };

  const handleOverrideChange = (key, value) => {
    setOverrides({ ...overrides, [key]: value });
  };

  const handleSaveOverrides = async () => {
    try {
      const token = localStorage.getItem("token");
      await axios.post(
        `http://localhost:5000/api/admin/set-fee/${selectedStudent._id}`,
        { overrides },
        { headers: { Authorization: `Bearer ${token}` } }
      );
      alert("Fee overrides saved!");
    } catch (err) {
      console.error(err);
      alert("Error saving overrides.");
    }
  };

  return (
    <div className="admin-fee-container">
      <div className="student-list">
        <h2>Students</h2>
        <ul>
          {students.map((stu) => (
            <li key={stu._id} onClick={() => handleStudentSelect(stu)}>
              {stu.name} (Class {stu.className})
            </li>
          ))}
        </ul>
      </div>

      {selectedStudent && (
        <div className="fee-editor">
          <h2>Edit Fees - {selectedStudent.name}</h2>
          <table className="fee-table">
            <thead>
              <tr>
                <th>Fee Type</th>
                <th>Amount (₹)</th>
              </tr>
            </thead>
            <tbody>
              {Object.keys(overrides).map((key) => (
                <tr key={key}>
                  <td>{key}</td>
                  <td>
                    <input
                      type="number"
                      value={overrides[key]}
                      onChange={(e) =>
                        handleOverrideChange(key, e.target.value)
                      }
                    />
                  </td>
                </tr>
              ))}
            </tbody>
          </table>

          <button className="save-btn" onClick={handleSaveOverrides}>
            Save Changes
          </button>

          <button
            className="fee-pay-btn"
            onClick={() => setShowPayPopup(true)}
          >
            Open Parent Fee Popup
          </button>
        </div>
      )}

      {/* Modal Popup */}
      {showPayPopup && (
        <div className="popup-overlay">
          <div className="popup-content">
            <button className="close-btn" onClick={() => setShowPayPopup(false)}>
              ✕
            </button>
            <ParentFeePage />
          </div>
        </div>
      )}
    </div>
  );
}
